"""The license inventory tool: the closure walk, the policy, and what a run writes."""

from __future__ import annotations

import json
from pathlib import Path
import zipfile

import pytest

from teachers_teammate.infrastructure.spacy_models import SPACY_MODEL_PINS
from tools.licenses import inventory

#: A lock in pip-compile's shape: a header, pins, and ``# via`` in both of its forms.
_LOCK = """\
#
# This file is autogenerated by pip-compile with Python 3.14
# by the following command:
#
#    bazel run //:requirements_addons.update
#
annotated-types==0.8.0
    # via pydantic
langchain-core==1.8.1
    # via teachers-teammate (pyproject.toml)
numpy==2.5.5
    # via
    #   langchain-core
    #   spacy
pydantic==2.14.3
    # via
    #   langchain-core
    #   spacy
pyside6-essentials==6.11.0
    # via teachers-teammate (pyproject.toml)
spacy==3.8.18
    # via teachers-teammate (pyproject.toml)
typer==0.21.0
    # via spacy
"""


def _into(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    """Point every path a run writes at *tmp_path*, so no test touches the committed store."""
    for name, relative in (
        ("STORE", ""),
        ("INVENTORY", "inventory.csv"),
        ("ASSET_CSV", "third_party_inventory.csv"),
        ("ASSET_TXT", "third_party_licenses.txt"),
        ("ASSET_LICENSE", "LICENSE.txt"),
    ):
        monkeypatch.setattr(inventory, name, tmp_path / relative)


def test_closure_follows_the_via_comments_from_the_roots() -> None:
    """
    Given  a lock that resolves the whole project, with pip-compile's ``# via`` comments
    When   the closure of the add-ons' own packages is worked out
    Then   it is what they reach, and the bundle's own packages stay out
    """
    closure = inventory.closure(_LOCK, ["spacy", "langchain-core"])

    assert [name for name, _version in closure] == [
        "annotated-types",
        "langchain-core",
        "numpy",
        "pydantic",
        "spacy",
        "typer",
    ]
    assert dict(closure)["spacy"] == "3.8.18"


def test_closure_is_empty_when_no_root_is_locked() -> None:
    """
    Given  a lock without a single package the roots name
    When   the closure is worked out
    Then   nothing is listed, instead of the whole lock
    """
    assert inventory.closure("numpy==2.5.5\n    # via teachers-teammate\n", ["spacy"]) == []


def test_a_package_in_both_closures_is_one_bundle_row(tmp_path: Path) -> None:
    """
    Given  an add-on lock that pins a package the bundle also carries, at another version
    When   the add-on rows are worked out
    Then   the package is not an add-on row — the bundle's row is the one that ships
    """
    lock = tmp_path / "requirements_addons_lock.txt"
    lock.write_text(_LOCK, encoding="utf-8")

    rows = inventory.addon_rows(lock, shipped=["numpy"])

    assert [row.component for row in rows] == [
        "annotated-types",
        "langchain-core",
        "pydantic",
        "spacy",
        "typer",
    ]


def _as_a_row(spelling: str) -> str:
    """Return the License column *spelling* leaves after the policy applied its ``[names]``."""
    policy = inventory.load_policy()
    return inventory.apply_policy([inventory.Row("pkg", "1.0", spelling, "addon")], policy)[
        0
    ].license


def test_an_or_expression_is_allowed_when_one_alternative_is() -> None:
    """
    Given  license expressions with alternatives, and one whose alternatives are all refused
    When   each is held against the policy
    Then   one alternative on the allow list is enough
    """
    policy = inventory.load_policy()

    assert inventory.refused_reason("LGPL-3.0-only OR GPL-2.0-only OR GPL-3.0-only", policy) is None
    assert inventory.refused_reason("GPL-3.0-only OR MIT", policy) is None
    assert inventory.refused_reason("GPL-2.0-only OR MIT", policy) is None
    assert inventory.refused_reason("MIT", policy) is None
    assert inventory.refused_reason("AGPL-3.0 OR SSPL-1.0", policy) is not None


def test_parentheses_group_the_alternatives_they_hold() -> None:
    """
    Given  an expression whose refused alternative sits inside parentheses
    When   it is held against the policy
    Then   the parentheses are read as grouping, and the `OR` inside them decides alone
    """
    policy = inventory.load_policy()

    assert inventory.refused_reason("MPL-2.0 AND (Apache-2.0 OR MIT)", policy) is None
    assert inventory.refused_reason("MIT AND (CDDL-1.0 OR AGPL-3.0)", policy) is not None


def test_an_exception_is_read_with_the_license_it_amends() -> None:
    """
    Given  a license with an exception, one listed in ``[allow]`` and one that is not
    When   each is held against the policy
    Then   the exception decides, and the license alone is no way out
    """
    policy = inventory.load_policy()

    assert inventory.refused_reason("GPL-2.0-or-later WITH Bootloader-exception", policy) is None
    assert inventory.refused_reason("GPL-3.0-or-later WITH GCC-exception-3.1", policy) is None
    assert (
        inventory.refused_reason("GPL-2.0-or-later WITH Classpath-exception-2.0", policy) is not None
    )
    assert inventory.refused_reason("AGPL-3.0 WITH Bootloader-exception", policy) is not None


def test_a_free_text_is_refused_until_a_name_folds_it() -> None:
    """
    Given  a License column holding a whole sentence, a spelling ``[names]`` folds, and where
           the fold lands
    When   each is held against the policy
    Then   the sentence is refused and the folded spelling passes
    """
    policy = inventory.load_policy()

    assert (
        inventory.refused_reason("BSD-3-Clause, Apache-2.0, dependency licenses", policy) is not None
    )
    assert inventory.refused_reason("GNU Library General Public License", policy) is not None

    applied = inventory.apply_policy(
        [inventory.Row("nl_core_news_sm", "3.8.0", "CC BY-SA 4.0", "addon", "model")], policy
    )
    assert applied[0].license == "CC-BY-SA-4.0"
    assert inventory.refused_reason(applied[0].license, policy) is None


@pytest.mark.parametrize(
    "spelling",
    [
        "GPL-3.0-only",
        "GPL-3.0-or-later",
        "GPLv3+",
        "GPL-2.0-or-later",
        "LGPL-2.1-or-later",
        "LGPL-3.0-only",
        "MPL-2.0",
        "Apache-2.0",
        "EPL-2.0 OR GPL-2.0-or-later",
        "MIT AND Apache-2.0",
        "Mozilla Public License 2.0 (MPL 2.0)",
        "GNU General Public License v3 (GPLv3)",
        "GNU General Public License v2 or later (GPLv2+)",
    ],
)
def test_a_license_gpl3_takes_along_is_allowed(spelling: str) -> None:
    """
    Given  the licenses of components a GPL-3.0 program may carry, as PyPI spells them
    When   each is folded by the policy and held against it
    Then   none is refused
    """
    assert inventory.refused_reason(_as_a_row(spelling), inventory.load_policy()) is None


@pytest.mark.parametrize(
    "spelling",
    [
        "GPL-2.0-only",
        "GPL",
        "AGPL-3.0",
        "EPL-1.0",
        "EPL-2.0",
        "Eclipse Public License 2.0",
        "CDDL-1.0",
        "BSD-4-Clause",
        "CC-BY-NC-4.0",
        "CC-BY-ND-4.0",
        "MPL-2.0-no-copyleft-exception",
        "OpenSSL",
        "Other/Proprietary License",
        "GNU Affero General Public License v3",
        "GNU Affero General Public License v3 or later (AGPLv3+)",
        "GNU General Public License v2 (GPLv2)",
        "Eclipse Public License 1.0",
        "Mozilla Public License 1.1 (MPL 1.1)",
        "Server Side Public License",
    ],
)
def test_a_license_gpl3_cannot_take_along_is_refused(spelling: str) -> None:
    """
    Given  the licenses that cannot join a GPL-3.0 program, and the ids no one has read
    When   each is folded by the policy and held against it
    Then   it is refused
    """
    assert inventory.refused_reason(_as_a_row(spelling), inventory.load_policy()) is not None


@pytest.mark.parametrize(
    "spelling",
    [
        "LGPL-3.0-only",
        "LGPL-2.1-or-later",
        "GNU Lesser General Public License v3 (LGPLv3)",
        "GNU Library or Lesser General Public License (LGPL)",
    ],
)
def test_the_lgpl_is_not_taken_for_the_gpl(spelling: str) -> None:
    """
    Given  LGPL licenses, which a GPL-3.0 program may link
    When   each is folded by the policy and held against it
    Then   none is refused — no GPL rule reads the Lesser or Library spelling
    """
    assert inventory.refused_reason(_as_a_row(spelling), inventory.load_policy()) is None


def test_a_package_that_states_no_license_is_refused_whatever_the_policy() -> None:
    """
    Given  PyPI's word for a package whose metadata names no license
    When   it is held against the policy
    Then   it is refused, and the reason says who has to read it
    """
    reason = inventory.refused_reason(inventory.UNKNOWN, inventory.load_policy())

    assert reason is not None
    assert "[accepted]" in reason


def test_an_and_expression_is_refused_when_any_part_is() -> None:
    """
    Given  a license expression whose parts all apply
    When   it is held against the policy
    Then   one refused part is enough, since the package cannot be used without it
    """
    policy = inventory.load_policy()

    assert inventory.refused_reason("MIT AND GPL-2.0-only", policy) is not None
    assert inventory.refused_reason("CC-BY-NC-4.0", policy) is not None


def test_license_of_prefers_the_expression_then_the_classifier_then_the_text() -> None:
    """
    Given  PyPI's three ways of naming a license
    When   the license is read
    Then   the expression wins, then the classifier, then the first line of the free text
    """
    assert inventory.license_of({"license_expression": "MIT"}) == "MIT"
    assert (
        inventory.license_of(
            {"classifiers": ["License :: OSI Approved :: Apache Software License"]}
        )
        == "Apache Software License"
    )
    assert inventory.license_of({"license": "BSD 3-Clause\n\nfull text"}) == "BSD 3-Clause"
    assert inventory.license_of({}) == "unknown"


def test_collect_names_the_package_it_could_not_read() -> None:
    """
    Given  a PyPI that answers for one package and fails for another
    When   the licenses are collected
    Then   the failure names the package instead of a bare traceback
    """

    def fetch(name: str, version: str) -> dict:
        if name == "broken":
            raise OSError("no route to host")
        return {"license_expression": "MIT"}

    rows = [inventory.Row("spacy", "3.8.18", "", "addon")]
    assert inventory.collect(rows, fetch) == [inventory.Row("spacy", "3.8.18", "MIT", "addon")]
    with pytest.raises(SystemExit, match=r"broken 1\.0"):
        inventory.collect([inventory.Row("broken", "1.0", "", "addon")], fetch)


def test_spacy_models_are_addon_rows_at_their_pinned_version() -> None:
    """
    Given  the models the app offers
    When   the tool works out its rows
    Then   each is an add-on row of kind model, at the version the app pins
    """
    rows = inventory.spacy_rows()

    assert [row.component for row in rows] == list(SPACY_MODEL_PINS)
    assert [row.version for row in rows] == list(SPACY_MODEL_PINS.values())
    assert {(row.scope, row.kind) for row in rows} == {("addon", "model")}


def test_collect_reads_a_spacy_model_license_from_its_meta_json() -> None:
    """
    Given  a spaCy model row and a meta JSON that states its license
    When   the licenses are collected
    Then   the row carries that license, and a model row that states its own is left alone
    """
    rows = [
        inventory.Row("en_core_web_sm", "3.8.0", "", "addon", "model"),
        inventory.Row("ppocr-small-det", "28fe5895", "Apache-2.0", "bundle", "model"),
    ]

    filled = inventory.collect(rows, fetch_model=lambda _name, _version: {"license": "MIT"})

    assert filled == [
        inventory.Row("en_core_web_sm", "3.8.0", "MIT", "addon", "model"),
        inventory.Row("ppocr-small-det", "28fe5895", "Apache-2.0", "bundle", "model"),
    ]


def test_check_env_names_what_the_inventory_does_not_list() -> None:
    """
    Given  a build environment holding a bundle row, a build row, the project itself, an
    add-on row and two distributions the inventory does not know
    When   the environment is held against the inventory
    Then   only the add-on and the two unknown ones are named — the project is exempt
    """
    rows = [
        inventory.Row("numpy", "2.5.4", "BSD-3-Clause", "bundle"),
        inventory.Row(
            "pyinstaller", "6.22.3", "GPL-2.0-or-later WITH Bootloader-exception", "build"
        ),
        inventory.Row("spacy", "3.8.18", "MIT", "addon"),
    ]

    found = inventory.environment_problems(
        rows,
        [
            ("numpy", "2.5.4"),
            ("pyinstaller", "6.22.3"),
            ("teachers-teammate", "0.6.0"),
            ("spacy", "3.8.18"),
            ("mystery", "1.0"),
            ("pillow", "13.0.0"),
        ],
    )

    assert found == [
        "mystery==1.0 is installed but is no bundle or build row",
        "pillow==13.0.0 is installed but is no bundle or build row",
        "spacy==3.8.18 is installed but is no bundle or build row",
    ]


def test_check_env_names_a_row_at_another_version() -> None:
    """
    Given  a build environment whose numpy is not the version the inventory lists
    When   the environment is held against the inventory
    Then   the mismatch is named with both versions
    """
    rows = [inventory.Row("numpy", "2.5.4", "BSD-3-Clause", "bundle")]

    assert inventory.environment_problems(rows, [("numpy", "2.5.5")]) == [
        "numpy==2.5.5 is installed, but the inventory lists 2.5.4"
    ]


def test_check_resolved_reads_a_pip_report(tmp_path: Path) -> None:
    """
    Given  a pip --dry-run --report file naming one package
    When   the report is read
    Then   its name is normalised and its version kept
    """
    report = tmp_path / "addon.json"
    report.write_text(
        json.dumps(
            {
                "version": "1",
                "install": [
                    {
                        "metadata": {"name": "LangChain_Core", "version": "0.3.1"},
                        "requested": True,
                    }
                ],
            }
        ),
        encoding="utf-8",
    )

    assert inventory.resolved_distributions(report) == [("langchain-core", "0.3.1")]


def test_check_resolved_reads_a_folder_of_reports(tmp_path: Path) -> None:
    """
    Given  a folder holding two reports, as the weekly job writes them
    When   the folder is read
    Then   every entry of both is returned
    """
    for name, package in (("a-newest", "spacy"), ("a-locked", "thinc")):
        (tmp_path / f"{name}.json").write_text(
            json.dumps({"install": [{"metadata": {"name": package, "version": "1.0"}}]}),
            encoding="utf-8",
        )

    assert inventory.resolved_distributions(tmp_path) == [("thinc", "1.0"), ("spacy", "1.0")]


def test_check_resolved_names_a_platform_only_dependency() -> None:
    """
    Given  an inventory with a bundle row and an add-on row
    When   a resolved install brings a package that is neither, and one at another version
    Then   both are named — the add-on lock is resolved on Linux, so this is the only check
           that sees a dependency which exists on one OS only
    """
    rows = [
        inventory.Row("numpy", "2.5.4", "BSD-3-Clause", "bundle"),
        inventory.Row("spacy", "3.8.18", "MIT", "addon"),
    ]

    found = inventory.resolved_problems(
        rows,
        [
            ("numpy", "2.5.4"),
            ("spacy", "3.8.17"),
            ("pywin32", "311"),
            ("teachers-teammate", "0.6.0"),
        ],
    )

    assert found == [
        "pywin32==311 would be installed but is no bundle or add-on row",
        "spacy==3.8.17 would be installed, but the inventory lists 3.8.18",
    ]


def test_check_resolved_passes_when_everything_is_listed() -> None:
    """
    Given  a resolved install that is exactly the bundle and add-on rows
    When   it is held against the inventory
    Then   nothing is reported
    """
    rows = [
        inventory.Row("numpy", "2.5.4", "BSD-3-Clause", "bundle"),
        inventory.Row("spacy", "3.8.18", "MIT", "addon"),
    ]

    assert inventory.resolved_problems(rows, [("numpy", "2.5.4"), ("spacy", "3.8.18")]) == []


def test_render_writes_a_header_and_one_row_per_component() -> None:
    """
    Given  two components with their licenses
    When   the CSV is rendered
    Then   it has a header and one row each, with no trailing blank line
    """
    text = inventory.render(
        [
            inventory.Row("numpy", "2.5.5", "BSD-3-Clause", "bundle"),
            inventory.Row("spacy", "3.8.18", "MIT", "addon"),
        ]
    )

    assert text == (
        "Component,Version,License,Scope,Kind\n"
        "numpy,2.5.5,BSD-3-Clause,bundle,package\n"
        "spacy,3.8.18,MIT,addon,package\n"
    )


def test_a_run_writes_the_inventory_and_the_copy_the_app_reads(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """
    Given  one add-on row and a PyPI that states its license
    When   the tool runs
    Then   the inventory and the app's copy hold the same row
    """
    monkeypatch.setattr(
        inventory, "expected", lambda _policy: [inventory.Row("spacy", "3.8.18", "", "addon")]
    )
    monkeypatch.setattr(inventory, "_pypi_info", lambda _n, _v: {"license_expression": "MIT"})
    _into(tmp_path, monkeypatch)

    assert inventory.main([]) == 0
    assert inventory.read_inventory(tmp_path / "inventory.csv") == [
        inventory.Row("spacy", "3.8.18", "MIT", "addon")
    ]
    assert (tmp_path / "third_party_inventory.csv").read_text(encoding="utf-8") == (
        "Component,Version,License,Scope,Kind\nspacy,3.8.18,MIT,addon,package\n"
    )


def test_main_refuses_a_denied_license_and_writes_nothing(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """
    Given  an add-on whose package is under a license we must not ship
    When   the inventory is written
    Then   the run fails, names the package and the reason, and leaves no file behind
    """
    monkeypatch.setattr(
        inventory, "expected", lambda _policy: [inventory.Row("spacy", "3.8.18", "", "addon")]
    )
    monkeypatch.setattr(inventory, "_pypi_info", lambda _n, _v: {"license_expression": "AGPL-3.0"})
    _into(tmp_path, monkeypatch)

    assert inventory.main([]) == 1
    assert not (tmp_path / "inventory.csv").exists()


def test_an_unknown_license_is_refused_until_it_is_listed() -> None:
    """
    Given  a package whose PyPI metadata names no license
    When   the rows are held against the policy
    Then   it is refused, unless a person listed it in ``[accepted]`` with a reason
    """
    policy = inventory.load_policy()
    rows = [
        inventory.Row("mystery", "1.0", "unknown", "addon"),
        inventory.Row("spacy", "3.8.18", "MIT", "addon"),
    ]

    found = inventory.problems(rows, policy)
    assert len(found) == 1
    assert found[0].startswith("mystery 1.0 is unknown")

    accepted = inventory.replace(policy, accepted={"mystery": "MIT text read in its sdist"})
    assert inventory.problems(rows, accepted) == []


def test_the_pypdfium2_rule_keeps_the_shipped_groups_and_inlines_the_shared_text(
    tmp_path: Path,
) -> None:
    """
    Given  a wheel whose BUILD_LICENSES/ holds the groups pypdfium2 ships and the ones it does not
    When   its texts are read
    Then   the shipped groups land under deps/, the others are dropped, and the #include is
           replaced by the text it names
    """
    wheel = tmp_path / "pypdfium2-5.15.2-py3-none-manylinux_2_17_x86_64.whl"
    prefix = "pypdfium2-5.15.2.dist-info/licenses/"
    entries = {
        "LICENSES/BSD-3-Clause.txt": "bsd\n",
        "BUILD_LICENSES/zlib.txt": "zlib\n",
        "BUILD_LICENSES/abseil.txt": "#include ./SHARED/Apache-2.0.txt\n",
        "BUILD_LICENSES/SHARED/Apache-2.0.txt": "apache\n",
        "BUILD_LICENSES/all_except_musl/llvm-libc.txt": "llvm\n",
        "BUILD_LICENSES/pbin_and_sbuild/brotli.txt": "brotli\n",
        "BUILD_LICENSES/android/catapult.txt": "android\n",
        "BUILD_LICENSES/v8_xfa/v8.txt": "v8\n",
    }
    with zipfile.ZipFile(wheel, "w") as archive:
        for name, text in entries.items():
            archive.writestr(prefix + name, text)

    assert inventory.wheel_texts("pypdfium2", wheel) == {
        "LICENSES/BSD-3-Clause.txt": b"bsd\n",
        "deps/zlib.txt": b"zlib\n",
        "deps/abseil.txt": b"apache\n",
        "deps/all_except_musl/llvm-libc.txt": b"llvm\n",
        "deps/pbin_and_sbuild/brotli.txt": b"brotli\n",
    }


def test_a_stamp_names_its_rows_and_the_version_it_was_written_for(tmp_path: Path) -> None:
    """
    Given  a hand-owned folder with a STAMP.toml
    When   the stamps of the store are read
    Then   the folder, its rows and its valid_for come back as written
    """
    folder = tmp_path / "curated" / "qt"
    folder.mkdir(parents=True)
    (folder / "STAMP.toml").write_text(
        'rows = ["pyside6-essentials", "shiboken6"]\nvalid_for = "6.12"\n', encoding="utf-8"
    )

    assert inventory.stamps(tmp_path) == [
        inventory.Stamp(folder, ("pyside6-essentials", "shiboken6"), "6.12")
    ]


def test_a_run_rewrites_texts_and_leaves_curated_alone(tmp_path: Path) -> None:
    """
    Given  a store with a stale text folder and a hand-owned ``curated/`` folder
    When   the texts are collected
    Then   the stale folder is gone and every file under ``curated/`` is untouched — the tool
           owns ``texts/`` and nothing else
    """
    store = tmp_path
    stale = store / "texts" / "gone-package"
    stale.mkdir(parents=True)
    (stale / "LICENSE").write_text("old\n", encoding="utf-8")
    curated = store / "curated" / "qt"
    curated.mkdir(parents=True)
    (curated / "STAMP.toml").write_text('rows = ["pyside6-essentials"]\n', encoding="utf-8")
    (curated / "qt_third_party.md").write_text("hand written\n", encoding="utf-8")

    inventory.collect_texts(
        [inventory.Row("langchain-core", "1.8.1", "MIT", "addon")],
        inventory.load_policy(),
        store,
    )

    assert not stale.exists()
    assert (curated / "STAMP.toml").read_text(encoding="utf-8") == (
        'rows = ["pyside6-essentials"]\n'
    )
    assert (curated / "qt_third_party.md").read_text(encoding="utf-8") == "hand written\n"


def _wheel(tmp_path: Path, names: dict[str, str]) -> Path:
    """Write a wheel holding *names* and return its path."""
    wheel = tmp_path / "pkg-1-py3-none-any.whl"
    with zipfile.ZipFile(wheel, "w") as archive:
        for name, text in names.items():
            archive.writestr(name, text)
    return wheel


def test_vendored_license_files_with_the_same_name_do_not_overwrite_each_other(
    tmp_path: Path,
) -> None:
    """
    Given  a wheel whose package and two vendored libraries each carry a file called LICENSE
    When   its license files are read
    Then   all three are kept, each under its path in the wheel
    """
    wheel = _wheel(
        tmp_path,
        {
            "pkg/LICENSE": "own",
            "pkg/_vendor/a/LICENSE": "a",
            "pkg/_vendor/b/LICENSE": "b",
            "pkg-1.dist-info/licenses/LICENSE": "dist",
            "pkg-1.dist-info/METADATA": "x",
            "pkg/code.py": "x",
        },
    )

    assert inventory.wheel_license_files(wheel) == {
        "pkg/LICENSE": b"own",
        "pkg/_vendor/a/LICENSE": b"a",
        "pkg/_vendor/b/LICENSE": b"b",
        "LICENSE": b"dist",
    }


def _entries(*names: str) -> list[dict]:
    """Return PyPI-style file entries for wheel *names*."""
    return [{"filename": name} for name in names]


def test_the_wheel_fits_the_bundles_python_and_the_newest_acceptable_macos() -> None:
    """
    Given  PyPI files for several Python tags, a free-threaded build and two macOS builds
    When   the macOS wheel is chosen for cp314
    Then   it is the newest one a macOS 15 build accepts, never the free-threaded or an older Python
    """
    files = _entries(
        "n-1-cp313-cp313-macosx_14_0_arm64.whl",
        "n-1-cp314-cp314t-macosx_14_0_arm64.whl",
        "n-1-cp314-cp314-macosx_11_0_arm64.whl",
        "n-1-cp314-cp314-macosx_14_0_arm64.whl",
        "n-1-cp314-cp314-macosx_15_0_arm64.whl",
        "n-1-cp314-cp314-macosx_26_0_arm64.whl",
        "n-1-cp314-cp314-manylinux_2_28_x86_64.whl",
    )

    assert (
        inventory.wheel_url(files, "macosx_arm64", "cp314")["filename"]
        == "n-1-cp314-cp314-macosx_15_0_arm64.whl"
    )
    assert "manylinux" in inventory.wheel_url(files, "manylinux", "cp314")["filename"]


def test_an_abi3_wheel_and_a_universal_wheel_are_found() -> None:
    """
    Given  an abi3 wheel built for an older Python, and a package with only a universal wheel
    When   the wheel is chosen for cp314
    Then   the abi3 wheel is taken for its platform, and the universal one where there is none
    """
    abi3 = _entries("q-1-cp39-abi3-win_amd64.whl", "q-1-py3-none-any.whl")

    assert inventory.wheel_url(abi3, "win_amd64", "cp314")["filename"].endswith("win_amd64.whl")
    assert inventory.wheel_url(abi3, "manylinux", "cp314")["filename"].endswith("none-any.whl")


def test_a_failed_download_leaves_the_old_texts_in_place(tmp_path: Path) -> None:
    """
    Given  a store with a text folder and a collect run whose fetch fails
    When   the texts are collected
    Then   the error reaches the caller and the old folder is still there
    """
    folder = tmp_path / "texts" / "pkg"
    folder.mkdir(parents=True)
    (folder / "LICENSE").write_text("old\n", encoding="utf-8")

    def failing(_name: str, _version: str) -> list[dict]:
        raise OSError("offline")

    with pytest.raises(OSError, match="offline"):
        inventory.collect_texts(
            [inventory.Row("pkg", "1", "MIT", "bundle")],
            inventory.load_policy(),
            tmp_path,
            fetch_files=failing,
        )

    assert (folder / "LICENSE").read_text(encoding="utf-8") == "old\n"
